                font = Player.HlGet(hl, i, Player.HlfSubject());
                if ((HhDocAgree(hl, font, 0, 0) > 0) && (HhDocAgree(hl, font, 0, 0) == HhDocAgree(hl, font, 0, 1))) {
                    both = HhDocAgree(hl, font, 0, 2);
                    dag = (HhDocAgree(hl, font, 0, 3) * 1000) / both;
                    if (Player.HlGet(hl, i, HlfBoth()) < HhAgreeWords()) {
                        Player.HlSet(hl, i, Player.HlfAgreement(), dag);
                    }
                    HhFontRescore(hl, i, 1);
                    changed += 1;
                }
            }
            i += 1;
        }
        // every flow word: its row's score
        while (j < nw) {
            ft = emon.Port.CellsAt(fw, (j * 24) + 15);
            r = HhFind(hl, Player.PlhFontPage(), emon.Port.CellsAt(fw, j * 24), emon.Port.CellsAt(fw, (j * 24) + 19));
            if ((ft >= 0) && (r >= 0)) {
                Evidence.FeSet(feats, ft, Evidence.XtFontHealth(), Player.HlGet(hl, r, Player.HlfScore()));
            }
            j += 1;
        }
        return changed;
    }
    internal static int HhImageOk(emon.Port.Cells images, int m) {
        // 1 for a visible image placement at least `img-min` each way.
        if (Evidence.ImGet(images, m, Evidence.MfVis()) != 0) {
            return 0;
        }
        if ((Evidence.ImGet(images, m, Evidence.MfX1()) - Evidence.ImGet(images, m, Evidence.MfX0())) < HhImgMin()) {
            return 0;
        }
        if ((Evidence.ImGet(images, m, Evidence.MfY1()) - Evidence.ImGet(images, m, Evidence.MfY0())) < HhImgMin()) {
            return 0;
        }
        return 1;
    }
    internal static int HhRuleRegion(emon.Port.Cells images, int page, int cx, int cy) {
        // The `images` row of the visible placement of the page that holds the point, else -1 (R0).
        int n = emon.Port.CellsLen(images) / 20;
        int m = 0;
        while (m < n) {
            if ((Evidence.ImGet(images, m, Evidence.MfPage()) == page) && (HhImageOk(images, m) == 1)) {
                if (((cx >= Evidence.ImGet(images, m, Evidence.MfX0())) && (cx < Evidence.ImGet(images, m, Evidence.MfX1()))) && ((cy >= Evidence.ImGet(images, m, Evidence.MfY0())) && (cy < Evidence.ImGet(images, m, Evidence.MfY1())))) {
                    return m;
                }
            }
            m += 1;
        }
        return -1;
    }
    internal static int HhDev(int dx, int dy) {
        // A rule's deviation from its axis in centi-degrees (signed, within +-1500 when it counts): 0 for a horizontal one; a
        // vertical one's from the vertical. -100000 for a slanted one that counts for neither.
        int a0 = Evidence.EvAngle(dx, dy);
        int a = a0 - ((a0 / 18000) * 18000);
        if (a <= HhAxis()) {
            return a;
        }
        if (a >= (18000 - HhAxis())) {
            return a - 18000;
        }
        if ((a >= (9000 - HhAxis())) && (a <= (9000 + HhAxis()))) {
            return a - 9000;
        }
        return -100000;
    }
    internal static int HhRegionRow(emon.Port.Cells hl, int page, int subject, int witness, int precision, int skew, int conf, int nrules) {
        int r = HhUpsert(hl, Player.PlhRegion(), page, subject);
        Player.HlSet(hl, r, HrgWitness(), witness);
        Player.HlSet(hl, r, HrgPrecision(), precision);
        Player.HlSet(hl, r, HrgSkew(), skew);
        Player.HlSet(hl, r, HrgConf(), conf);
        Player.HlSet(hl, r, HrgRules(), nrules);
        Player.HlSet(hl, r, Player.HlfScore(), HhRegionScore(witness, precision, skew, conf));
        return r;
    }
    internal static int HhRegionMeasure(int page, emon.Port.Cells images, emon.Port.Cells rules, int region, int want) {
        // The tracer's measures of one region of a page: want 0 the number of its rules, 1 the mean rule confidence (-1 for none or
        // unknown), 2 the skew component (-1 with fewer than two axis-aligned rules): 1000 at a spread of the rules' deviations
        // of at most `skew-ok`, falling to 0 at `skew-bad`.
        int n = emon.Port.CellsLen(rules) / 20;
        int i = 0;
        int nr = 0;
        int csum = 0;
        int cn = 0;
        int axis = 0;
        int lo = 100000;
        int hi = -100000;
        int dx = 0;
        int dy = 0;
        int d = 0;
        int c = 0;
        while (i < n) {
            if (Evidence.RlGet(rules, i, Evidence.RlfPage()) == page) {
                dx = (Evidence.RlGet(rules, i, Evidence.RlfLx0()) + Evidence.RlGet(rules, i, Evidence.RlfLx1())) / 2;
                dy = (Evidence.RlGet(rules, i, Evidence.RlfLy0()) + Evidence.RlGet(rules, i, Evidence.RlfLy1())) / 2;
                if (HhRuleRegion(images, page, dx, dy) == region) {
                    nr += 1;
                    c = Evidence.RlGet(rules, i, Evidence.RlfConf());
                    if (c >= 0) {
                        csum += c;
                        cn += 1;
                    }
                    d = HhDev(Evidence.RlGet(rules, i, Evidence.RlfLx1()) - Evidence.RlGet(rules, i, Evidence.RlfLx0()), Evidence.RlGet(rules, i, Evidence.RlfLy1()) - Evidence.RlGet(rules, i, Evidence.RlfLy0()));
                    if (d > -100000) {
                        axis += 1;
                        if (d < lo) {
                            lo = d;
                        }
                        if (d > hi) {
                            hi = d;
                        }
                    }
                }
            }
            i += 1;
        }
        if (want == 0) {
            return nr;
        }
        if (want == 1) {
            return HhPool(csum, cn);
        }
        if (axis < 2) {
            return -1;
        }
        return HhDown(hi - lo, HhSkewOk(), HhSkewBad());
    }
    public static int HlRegions(int page, emon.Port.Cells images, emon.Port.Cells rules, int witness, int precision, emon.Port.Cells hl) {
        // The page's graphics regions (see the head): R0 first (subject -1), then one row per visible placement of at least
        // `img-min`. An image region borrows R0's tracer precision and has no vector witness of its own.
        int ni = emon.Port.CellsLen(images) / 20;
        int m = 0;
        int rows = 0;
        int n0 = HhRegionMeasure(page, images, rules, -1, 0);
        int prec = precision;
        HhRegionRow(hl, page, -1, witness, precision, HhRegionMeasure(page, images, rules, -1, 2), HhRegionMeasure(page, images, rules, -1, 1), n0);
        rows = 1;
        while (m < ni) {
            if ((Evidence.ImGet(images, m, Evidence.MfPage()) == page) && (HhImageOk(images, m) == 1)) {
                HhRegionRow(hl, page, m, -1, prec, HhRegionMeasure(page, images, rules, m, 2), HhRegionMeasure(page, images, rules, m, 1), HhRegionMeasure(page, images, rules, m, 0));
                rows += 1;
            }
            m += 1;
        }
        return rows;
    }
}
